import { ChevronLeftIcon, ChevronRightIcon, PauseIcon, PlayIcon } from '@advui/icons'
import {
  Children,
  type ReactNode,
  createContext,
  forwardRef,
  isValidElement,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
} from 'react'
import { AccessibilityInfo } from 'react-native'
import {
  type GetProps,
  type SpaceTokens,
  type TamaguiElement,
  View,
  type ViewProps,
  XStack,
  isWeb,
  styled,
  useComposedRefs,
  withStaticProperties,
} from 'tamagui'
import { useBreakpointValue } from '../../hooks/useBreakpoint'
import { useControllableState } from '../../hooks/useControllableState'
import { useReducedMotion } from '../../hooks/useReducedMotion'
import { useRipple } from '../../hooks/useRipple'
import { ariaState } from '../../utils/ariaState'
import type { Responsive } from '../../utils/responsive'
import { visuallyHidden } from '../../utils/visuallyHidden'
import { IconButton } from '../icon-button/IconButton'
import { Text } from '../typography/Text'
import { CarouselTrack } from './CarouselTrack'
import {
  type CarouselTrackHandle,
  type CarouselTrackKey,
  SlideStyleContext,
  lastIndexFor,
} from './shared'

export interface CarouselLabels {
  /** What the carousel is, read after its name (web). Default: "carousel". */
  carousel: string
  /** What a slide is, read after its name (web). Default: "slide". */
  slide: string
  /** A slide's name (web). Default: "3 of 5". */
  slideName: (index: number, count: number) => string
  /** Announced when the slide changes, except by autoplay. Default: "Slide 3 of 5". */
  position: (index: number, count: number) => string
  previous: string
  next: string
  /** A dot's name. Default: "Go to slide 3". */
  goTo: (index: number) => string
  play: string
  pause: string
}

const defaultLabels: CarouselLabels = {
  carousel: 'carousel',
  slide: 'slide',
  slideName: (index, count) => `${index + 1} of ${count}`,
  position: (index, count) => `Slide ${index + 1} of ${count}`,
  previous: 'Previous slide',
  next: 'Next slide',
  goTo: (index) => `Go to slide ${index + 1}`,
  play: 'Play slide show',
  pause: 'Pause slide show',
}

const focusRing = {
  outlineColor: '$ring',
  outlineStyle: 'solid',
  outlineWidth: 2,
  outlineOffset: 2,
} as const

const CarouselFrame = styled(View, {
  name: 'Carousel',
  width: '100%',
  gap: '$3',
  // The controls come first in the tree, so keyboard and screen-reader users
  // meet the pause button before the slides move under them (WAI-ARIA APG),
  // and show under the slides.
  flexDirection: 'column-reverse',
})

export interface CarouselProps extends Omit<GetProps<typeof CarouselFrame>, 'children' | 'gap'> {
  /** The slides: `Carousel.Item` elements, or any elements, one per slide. */
  children: ReactNode
  /** Names the carousel, e.g. "Featured articles". Recommended. */
  'aria-label'?: string
  /** The slide first in view, when you control it. */
  index?: number
  /** Starting `index` when uncontrolled. Default: 0. */
  defaultIndex?: number
  /** Called with the new `index` after a button, dot, key, swipe or autoplay moves it. */
  onIndexChange?: (index: number) => void
  /** Slides in view at once, or a mobile-first map. Fractions show part of the next one. Default: 1. */
  slidesPerView?: Responsive<number>
  /** Space between slides (token). Default: `$4`. */
  gap?: SpaceTokens
  /** Next on the last slide goes back to the first, and Previous on the first to the last. */
  loop?: boolean
  /** Moves to the next slide on its own: `true` every 5 seconds, or a delay in milliseconds. */
  autoplay?: boolean | number
  /** Previous and next buttons. Default: true. */
  showArrows?: boolean
  /** A dot per slide that can come first. Default: true. */
  showDots?: boolean
  /** Button names, role descriptions and announcements, for translation. */
  labels?: Partial<CarouselLabels>
}

interface SlideInfo {
  roleDescription: string
  label: string
}

const SlideContext = createContext<SlideInfo | null>(null)

export type CarouselItemProps = ViewProps

/**
 * One slide. It is the slide itself, so style it (padding, background) like
 * a View; Carousel sets its width.
 */
export const CarouselItem = forwardRef<TamaguiElement, CarouselItemProps>(function CarouselItem(
  { style, ...props },
  ref,
) {
  const slide = useContext(SlideContext)
  const { style: slideStyle, ...layout } = useContext(SlideStyleContext)
  return (
    <View
      ref={ref}
      {...layout}
      {...(isWeb &&
        slide && {
          role: 'group',
          'aria-roledescription': slide.roleDescription,
          'aria-label': slide.label,
        })}
      {...(slideStyle || style
        ? { style: { ...(slideStyle as object), ...(style as object) } }
        : null)}
      {...props}
    />
  )
})

function Dot({
  active,
  label,
  controls,
  onPress,
}: {
  active: boolean
  label: string
  controls: string
  onPress: () => void
}) {
  const ripple = useRipple({ color: '$foreground' })
  return (
    <View
      {...(isWeb
        ? {
            render: 'button',
            type: 'button',
            padding: 0,
            borderWidth: 0,
            'aria-current': active || undefined,
            'aria-controls': controls,
          }
        : { accessible: true, role: 'button', 'aria-selected': ariaState(active) })}
      aria-label={label}
      // A 24px target around an 8px dot (WCAG 2.5.8).
      width="$6"
      height="$6"
      alignItems="center"
      justifyContent="center"
      borderRadius="$full"
      backgroundColor="transparent"
      cursor="pointer"
      hoverStyle={{ backgroundColor: '$accent' }}
      focusVisibleStyle={focusRing}
      onPress={onPress}
      {...ripple.props}
    >
      {ripple.element}
      <View
        width={active ? '$5' : '$2'}
        height="$2"
        borderRadius="$full"
        backgroundColor={active ? '$primary' : '$mutedForeground'}
      />
    </View>
  )
}

/**
 * A row of slides shown one (or a few) at a time, with previous and next
 * buttons, dots, swipe on touch screens and optional autoplay.
 */
const CarouselRoot = forwardRef<TamaguiElement, CarouselProps>(function Carousel(
  {
    children,
    'aria-label': label,
    index: indexProp,
    defaultIndex = 0,
    onIndexChange,
    slidesPerView = 1,
    gap = '$4',
    loop = false,
    autoplay = false,
    showArrows = true,
    showDots = true,
    labels: labelsProp,
    ...props
  },
  ref,
) {
  const labels = { ...defaultLabels, ...labelsProp }
  const slides = Children.toArray(children)
  const count = slides.length
  const perView = Math.max(1, useBreakpointValue(slidesPerView) ?? 1)
  const lastIndex = lastIndexFor(count, perView)
  const [rawIndex, setIndex] = useControllableState({
    value: indexProp,
    defaultValue: defaultIndex,
    onChange: onIndexChange,
  })
  const index = Math.min(Math.max(0, Math.round(rawIndex) || 0), lastIndex)
  const trackId = useId()
  const reducedMotion = useReducedMotion()

  // Scroll the track when the index changes anywhere but in the track itself.
  const trackRef = useRef<CarouselTrackHandle>(null)
  const shownRef = useRef<number | null>(null)
  useEffect(() => {
    if (shownRef.current === index) return
    // The first scroll, to `defaultIndex`, jumps.
    const animated = shownRef.current !== null && !reducedMotion
    shownRef.current = index
    trackRef.current?.scrollToIndex(index, animated)
  }, [index, reducedMotion])

  const onSettle = (settled: number) => {
    shownRef.current = settled
    setIndex(settled)
  }
  const goTo = (next: number) => setIndex(Math.min(Math.max(0, next), lastIndex))
  const move = (by: 1 | -1) => {
    const next = index + by
    if (next >= 0 && next <= lastIndex) goTo(next)
    else if (loop) goTo(next < 0 ? lastIndex : 0)
  }
  const onKey = (key: CarouselTrackKey) => {
    if (key === 'first') goTo(0)
    else if (key === 'last') goTo(lastIndex)
    else move(key === 'next' ? 1 : -1)
  }

  // Autoplay waits while the pointer is over the carousel, focus is in it or
  // a finger is on it. Users who ask for less motion get it paused; the play
  // button still starts it.
  const delay = autoplay === true ? 5000 : typeof autoplay === 'number' ? Math.max(0, autoplay) : 0
  const [playing, setPlaying] = useState(true)
  const choseRef = useRef(false)
  useEffect(() => {
    if (reducedMotion && !choseRef.current) setPlaying(false)
  }, [reducedMotion])
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const [dragging, setDragging] = useState(false)
  const rotating = delay > 0 && lastIndex > 0 && playing && !hovered && !focused && !dragging

  const autoRef = useRef(false)
  const advanceRef = useRef(() => {})
  advanceRef.current = () => {
    autoRef.current = true
    setIndex(index >= lastIndex ? 0 : index + 1)
  }
  useEffect(() => {
    if (!rotating) return
    const timer = setTimeout(() => advanceRef.current(), delay)
    return () => clearTimeout(timer)
  }, [rotating, index, delay])

  const frameRef = useRef<HTMLElement | null>(null)
  const composedRef = useComposedRefs(ref, frameRef as never)
  useEffect(() => {
    const el = frameRef.current
    if (!isWeb || !el || delay <= 0) return
    const enter = () => setHovered(true)
    const leave = () => setHovered(false)
    const focusIn = () => setFocused(true)
    const focusOut = (event: FocusEvent) => {
      if (!el.contains(event.relatedTarget as Node | null)) setFocused(false)
    }
    el.addEventListener('pointerenter', enter)
    el.addEventListener('pointerleave', leave)
    el.addEventListener('focusin', focusIn)
    el.addEventListener('focusout', focusOut)
    return () => {
      el.removeEventListener('pointerenter', enter)
      el.removeEventListener('pointerleave', leave)
      el.removeEventListener('focusin', focusIn)
      el.removeEventListener('focusout', focusOut)
    }
  }, [delay])

  // Say where the user is after they move. Not when autoplay moves: the APG
  // turns the live region off while a carousel turns by itself.
  const [message, setMessage] = useState({ text: '', count: 0 })
  const announcedRef = useRef(index)
  const position = labels.position(index, count)
  useEffect(() => {
    if (announcedRef.current === index) return
    announcedRef.current = index
    const auto = autoRef.current
    autoRef.current = false
    if (auto) return
    if (isWeb) setMessage((current) => ({ text: position, count: current.count + 1 }))
    else AccessibilityInfo.announceForAccessibility(position)
  }, [index, position])

  const controlled = isWeb ? { 'aria-controls': trackId } : null
  const controls =
    lastIndex > 0 && (delay > 0 || showArrows || showDots) ? (
      <XStack alignItems="center" justifyContent="center" gap="$2" flexWrap="wrap">
        {delay > 0 ? (
          <IconButton
            size="sm"
            circular
            aria-label={playing ? labels.pause : labels.play}
            icon={playing ? <PauseIcon /> : <PlayIcon />}
            onPress={() => {
              choseRef.current = true
              setPlaying(!playing)
            }}
            {...controlled}
          />
        ) : null}
        {showArrows ? (
          <IconButton
            size="sm"
            circular
            variant="outline"
            aria-label={labels.previous}
            icon={<ChevronLeftIcon />}
            disabled={!loop && index === 0}
            onPress={() => move(-1)}
            {...controlled}
          />
        ) : null}
        {showDots ? (
          <XStack alignItems="center">
            {Array.from({ length: lastIndex + 1 }, (_, i) => (
              <Dot
                key={i}
                active={i === index}
                label={labels.goTo(i)}
                controls={trackId}
                onPress={() => goTo(i)}
              />
            ))}
          </XStack>
        ) : null}
        {showArrows ? (
          <IconButton
            size="sm"
            circular
            variant="outline"
            aria-label={labels.next}
            icon={<ChevronRightIcon />}
            disabled={!loop && index === lastIndex}
            onPress={() => move(1)}
            {...controlled}
          />
        ) : null}
      </XStack>
    ) : null

  return (
    <CarouselFrame
      ref={composedRef}
      {...(isWeb && { role: 'region', 'aria-roledescription': labels.carousel })}
      aria-label={label}
      {...props}
    >
      {controls}
      <CarouselTrack
        ref={trackRef}
        id={trackId}
        index={index}
        count={count}
        slidesPerView={slidesPerView}
        perView={perView}
        lastIndex={lastIndex}
        gap={gap}
        onSettle={onSettle}
        onDragChange={setDragging}
        onKey={onKey}
      >
        {slides.map((child, i) => (
          <SlideContext.Provider
            key={isValidElement(child) && child.key != null ? child.key : i}
            value={{ roleDescription: labels.slide, label: labels.slideName(i, count) }}
          >
            {isValidElement(child) && child.type === CarouselItem ? (
              child
            ) : (
              <CarouselItem>{child}</CarouselItem>
            )}
          </SlideContext.Provider>
        ))}
      </CarouselTrack>
      {isWeb ? (
        <View role="status" aria-live="polite" {...visuallyHidden}>
          {message.text ? <Text key={message.count}>{message.text}</Text> : null}
        </View>
      ) : null}
    </CarouselFrame>
  )
})

export const Carousel = withStaticProperties(CarouselRoot, { Item: CarouselItem })

import { type KeyboardEvent, forwardRef, useEffect, useImperativeHandle, useRef } from 'react'
import { type Token, View, type ViewProps, getTokenValue } from 'tamagui'
import { responsiveStyle } from '../../utils/responsive'
import {
  type CarouselTrackHandle,
  type CarouselTrackKey,
  type CarouselTrackProps,
  SlideStyleContext,
  indexAt,
} from './shared'

/** Slide width for `perView` slides with `gap` pixels between them. */
function slideWidth(perView: number, gap: number) {
  const count = Math.max(1, perView)
  return count === 1 ? '100%' : `calc((100% - ${(count - 1) * gap}px) / ${count})`
}

const keys: Record<string, [CarouselTrackKey, CarouselTrackKey] | undefined> = {
  // [left to right, right to left]
  ArrowLeft: ['previous', 'next'],
  ArrowRight: ['next', 'previous'],
  Home: ['first', 'first'],
  End: ['last', 'last'],
}

/**
 * Web: a row that scrolls sideways and snaps each slide to its start (CSS
 * scroll snap), so touch, trackpads and the scroll wheel move it natively.
 * Slide widths are CSS, with a media query per breakpoint, so the server
 * renders them right.
 */
export const CarouselTrack = forwardRef<CarouselTrackHandle, CarouselTrackProps>(
  function CarouselTrack({ id, slidesPerView, lastIndex, gap, onSettle, onKey, children }, ref) {
    const trackRef = useRef<HTMLElement | null>(null)
    const gapPx = (getTokenValue(gap as Token, 'space') as number | undefined) ?? 0

    // Read from the page each time: widths follow the breakpoint and the font.
    const measure = () => {
      const el = trackRef.current
      if (!el) return null
      const [first, second] = Array.from(el.children) as HTMLElement[]
      const step = first && second ? Math.abs(second.offsetLeft - first.offsetLeft) : el.clientWidth
      const rtl = getComputedStyle(el).direction === 'rtl'
      return { el, step, max: el.scrollWidth - el.clientWidth, rtl }
    }

    useImperativeHandle(ref, () => ({
      scrollToIndex(index, animated) {
        const track = measure()
        if (!track) return
        const left = Math.min(index * track.step, Math.max(0, track.max))
        // Right to left, scrollLeft runs from 0 down to negative numbers.
        track.el.scrollTo({
          left: track.rtl ? -left : left,
          behavior: animated ? 'smooth' : 'instant',
        })
      },
    }))

    const settleRef = useRef(() => {})
    settleRef.current = () => {
      const track = measure()
      if (track) onSettle(indexAt(Math.abs(track.el.scrollLeft), track.step, track.max, lastIndex))
    }
    useEffect(() => {
      const el = trackRef.current
      if (!el) return
      let timer: ReturnType<typeof setTimeout> | undefined
      const settle = () => {
        clearTimeout(timer)
        settleRef.current()
      }
      // `scrollend` where the browser has it; elsewhere a pause in scroll events.
      const onScroll = () => {
        clearTimeout(timer)
        timer = setTimeout(settle, 120)
      }
      el.addEventListener('scroll', onScroll, { passive: true })
      el.addEventListener('scrollend', settle)
      return () => {
        clearTimeout(timer)
        el.removeEventListener('scroll', onScroll)
        el.removeEventListener('scrollend', settle)
      }
    }, [])

    const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
      // Keys inside a slide (a text field, a link) are left alone.
      if (event.target !== event.currentTarget) return
      const pair = keys[event.key]
      if (!pair) return
      event.preventDefault()
      onKey(pair[getComputedStyle(event.currentTarget).direction === 'rtl' ? 1 : 0])
    }

    const slideStyle = {
      flexShrink: 0,
      ...responsiveStyle('width', slidesPerView, (perView: number) => slideWidth(perView, gapPx)),
      style: { scrollSnapAlign: 'start', scrollSnapStop: 'always' },
    } as ViewProps

    return (
      <View
        ref={trackRef as never}
        id={id}
        // Hides the scrollbar (GlobalStyles); the buttons, dots and swipes move it.
        className="aui-carousel-track"
        // Keyboard users reach slides without links this way, and page with the arrow keys.
        tabIndex={0}
        flexDirection="row"
        gap={gap}
        overflowX="auto"
        overflowY="hidden"
        style={{ scrollSnapType: 'x mandatory', overscrollBehaviorX: 'contain' }}
        focusVisibleStyle={{
          outlineColor: '$ring',
          outlineStyle: 'solid',
          outlineWidth: 2,
          outlineOffset: 2,
        }}
        onKeyDown={onKeyDown as never}
      >
        <SlideStyleContext.Provider value={slideStyle}>{children}</SlideStyleContext.Provider>
      </View>
    )
  },
)

import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react'
import { type NativeScrollEvent, type NativeSyntheticEvent, ScrollView } from 'react-native'
import { type Token, getTokenValue } from 'tamagui'
import {
  type CarouselTrackHandle,
  type CarouselTrackProps,
  SlideStyleContext,
  indexAt,
} from './shared'

type ScrollEvent = NativeSyntheticEvent<NativeScrollEvent>

/**
 * Native: a horizontal ScrollView that snaps to each slide. Percentages do
 * not size children of a horizontal ScrollView, so slide widths come from its
 * measured width.
 */
export const CarouselTrack = forwardRef<CarouselTrackHandle, CarouselTrackProps>(
  function CarouselTrack(
    { index, count, perView, lastIndex, gap, onSettle, onDragChange, children },
    ref,
  ) {
    const scrollRef = useRef<ScrollView>(null)
    const [width, setWidth] = useState(0)
    const gapPx = (getTokenValue(gap as Token, 'space') as number | undefined) ?? 0
    const slideWidth = width ? (width - (perView - 1) * gapPx) / perView : 0
    const step = slideWidth + gapPx
    const max = Math.max(0, count * slideWidth + (count - 1) * gapPx - width)
    const offsets = Array.from({ length: lastIndex + 1 }, (_, i) => Math.min(i * step, max))

    const geometry = useRef({ width, offsets })
    geometry.current = { width, offsets }
    const scrollTo = (target: number, animated: boolean) => {
      const { width: measured, offsets: stops } = geometry.current
      // Before the first layout there is nothing to scroll; the layout effect shows `index`.
      if (measured) scrollRef.current?.scrollTo({ x: stops[target] ?? 0, animated })
    }

    useImperativeHandle(ref, () => ({ scrollToIndex: scrollTo }))

    // After the first layout, and when the width changes (rotation), show the
    // current slide. Only a new layout runs it; index changes scroll from Carousel.
    const indexRef = useRef(index)
    indexRef.current = index
    const layoutKey = `${width}:${perView}:${gapPx}:${count}`
    useEffect(() => {
      scrollTo(indexRef.current, false)
    }, [layoutKey])

    // A pause in scroll events ends a swipe, a snap or a scrollTo alike, and
    // also the scroll a screen reader makes to reach a slide.
    const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
    useEffect(() => () => clearTimeout(timer.current), [])
    const settle = (x: number) => {
      clearTimeout(timer.current)
      if (width) onSettle(indexAt(x, step, max, lastIndex))
    }
    const onScroll = (event: ScrollEvent) => {
      const x = event.nativeEvent.contentOffset.x
      clearTimeout(timer.current)
      timer.current = setTimeout(() => settle(x), 120)
    }

    return (
      <ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        snapToOffsets={width ? offsets : undefined}
        decelerationRate="fast"
        // One slide per swipe, as on web (`scroll-snap-stop`).
        disableIntervalMomentum
        // Android: inside a scrolling screen, sideways swipes still reach it.
        nestedScrollEnabled
        scrollEventThrottle={16}
        onLayout={(event) => setWidth(event.nativeEvent.layout.width)}
        onScroll={onScroll}
        onScrollBeginDrag={() => onDragChange(true)}
        onScrollEndDrag={() => onDragChange(false)}
        onMomentumScrollEnd={(event: ScrollEvent) => settle(event.nativeEvent.contentOffset.x)}
        contentContainerStyle={{ gap: gapPx }}
        // Hidden for the one frame before the slides have their widths.
        style={{ opacity: width ? 1 : 0 }}
      >
        <SlideStyleContext.Provider
          value={{ flexShrink: 0, ...(slideWidth ? { width: slideWidth } : null) }}
        >
          {children}
        </SlideStyleContext.Provider>
      </ScrollView>
    )
  },
)

import { type ReactNode, createContext } from 'react'
import type { SpaceTokens, ViewProps } from 'tamagui'
import type { Responsive } from '../../utils/responsive'

/** What Carousel asks of the platform's track. */
export interface CarouselTrackHandle {
  /** Scrolls until slide `index` is first in view, or the track's end is. */
  scrollToIndex: (index: number, animated: boolean) => void
}

export type CarouselTrackKey = 'previous' | 'next' | 'first' | 'last'

export interface CarouselTrackProps {
  id: string
  /** The slide first in view. Native returns to it when the track's width changes. */
  index: number
  count: number
  slidesPerView: Responsive<number>
  /** `slidesPerView` at the current breakpoint. */
  perView: number
  lastIndex: number
  gap: SpaceTokens
  /** Called with the slide first in view once scrolling stops. */
  onSettle: (index: number) => void
  /** Native: a finger is on the track, so autoplay waits. */
  onDragChange: (dragging: boolean) => void
  /** Web: an arrow key, Home or End on the focused track. */
  onKey: (key: CarouselTrackKey) => void
  children: ReactNode
}

/** Width and snap style of every slide, set by the track. */
export const SlideStyleContext = createContext<ViewProps>({})

/**
 * The last slide that can be first in view. With 2.5 slides per view and 5
 * slides that is slide 3 (index 3): the track ends half-way through it.
 */
export function lastIndexFor(count: number, perView: number) {
  // The small margin keeps 5 - 3.0000001 from counting as one more stop.
  return Math.max(0, Math.ceil(count - perView - 0.001))
}

/**
 * The slide first in view at scroll offset `x`, for slides `step` apart on a
 * track that ends at `max`. Stops past `max` are clamped to it, so the end of
 * the track is the last stop.
 */
export function indexAt(x: number, step: number, max: number, lastIndex: number) {
  if (step <= 0) return 0
  if (max > 0 && x >= max - 1) return lastIndex
  return Math.min(lastIndex, Math.max(0, Math.round(x / step)))
}

